import { z } from 'zod';

export const registerDeviceSchema = z.object({
  /** Employee the device belongs to. Admins may register a device for anyone. */
  userId: z.string().uuid('userId must be a UUID').optional(),
  /** Human readable name, e.g. "Ramesh's Phone". */
  deviceName: z.string().trim().min(2, 'deviceName is required').max(120),
  /**
   * Stable code generated by the Android app (e.g. a hash of ANDROID_ID).
   * Unique per employee — re-registering the same phone returns a conflict.
   */
  deviceCode: z.string().trim().min(4, 'deviceCode is required').max(60),
  manufacturer: z.string().trim().max(120).optional(),
  model: z.string().trim().max(120).optional(),
  androidVersion: z.string().trim().max(40).optional(),
  appVersion: z.string().trim().max(40).optional(),
});

export const listDevicesQuerySchema = z.object({
  userId: z.string().uuid().optional(),
  status: z.enum(['ACTIVE', 'REVOKED']).optional(),
});

export const deviceIdParamSchema = z.object({
  id: z.string().uuid('id must be a UUID'),
});

export type RegisterDeviceInput = z.infer<typeof registerDeviceSchema>;
export type ListDevicesQuery = z.infer<typeof listDevicesQuerySchema>;
